import receiverEvents from "../const/receiverEvents";
import receiverState from "../const/receiverState";

class CafReceiverPlayer {
  constructor() {
    this.context = cast.framework.CastReceiverContext.getInstance();
    this.playerManager = this.context.getPlayerManager();
    this.state = receiverState.IDLE;
    this.drmConfig = null;
  }

  initialize() {
    this._registerLoadInterceptor();
    this._registerPlayerEvents();

    // playbackConfig controls default license/manifest request behavior
    // for CAF's built-in (Shaka-based) player.
    const playbackConfig = new cast.framework.PlaybackConfig();
    // autoResumeDuration, manifestRequestHandler, licenseRequestHandler, etc.
    // get set per-request inside the LOAD interceptor below, since DRM
    // config arrives with each LOAD request, not at startup.

    this.context.start({ playbackConfig });

    this._dispatch(receiverEvents.READY, {});
  }

  // Reads customReceiverConfig sent by the Bitmovin sender (see
  // src/solutions/bitmovin/tools/castConfig.js) and configures DRM before
  // CAF's default player handles the LOAD.
  _registerLoadInterceptor() {
    this.playerManager.setMessageInterceptor(
      cast.framework.messages.MessageType.LOAD,
      (loadRequestData) => {
        this._setState(receiverState.LOADING);

        const customData = loadRequestData.customData || {};
        if (customData.drmConfig) {
          try {
            this.drmConfig = JSON.parse(customData.drmConfig);
            this._applyDrmConfig(loadRequestData, this.drmConfig);
          } catch (error) {
            this._dispatch(receiverEvents.ERROR, {
              message: "Failed to parse drmConfig from customData",
              error,
            });
          }
        }

        // Must return the (possibly modified) loadRequestData for the
        // default receiver load handler to proceed.
        return loadRequestData;
      },
    );
  }

  // Translates your existing assetInfo.js-shaped drmConfig into CAF's
  // per-request license fields. Extend per key system as you add support.
  _applyDrmConfig(loadRequestData, drmConfig) {
    const media = loadRequestData.media;

    if (drmConfig.widevine) {
      media.customData = { ...media.customData, licenseUrl: drmConfig.widevine.laURL };
      this.playerManager.setLicenseRequestHandler((requestInfo) => {
        requestInfo.url = drmConfig.widevine.laURL;
        if (drmConfig.widevine.requestHeaderKey) {
          requestInfo.withCredentials = false;
          requestInfo.headers = {
            ...requestInfo.headers,
            ...drmConfig.widevine.requestHeaderKey,
          };
        }
        return requestInfo;
      });
    }

    // PlayReady / FairPlay follow the same shape — add as needed, same
    // pattern as each local adapter's own configureDRM().
  }

  _registerPlayerEvents() {
    const E = cast.framework.events.EventType;

    this.playerManager.addEventListener(E.PLAYER_LOAD_COMPLETE, () => {
      this._setState(receiverState.PLAYING);
    });

    this.playerManager.addEventListener(E.PLAYING, () => {
      this._setState(receiverState.PLAYING);
      this._dispatch(receiverEvents.PLAYING, {});
    });

    this.playerManager.addEventListener(E.PAUSE, () => {
      this._setState(receiverState.PAUSED);
      this._dispatch(receiverEvents.PAUSED, {});
    });

    this.playerManager.addEventListener(E.BUFFERING, () => {
      this._setState(receiverState.BUFFERING);
      this._dispatch(receiverEvents.BUFFERING, {});
    });

    this.playerManager.addEventListener(E.ENDED, () => {
      this._setState(receiverState.ENDED);
      this._dispatch(receiverEvents.ENDED, {});
    });

    this.playerManager.addEventListener(E.ERROR, (event) => {
      this._dispatch(receiverEvents.ERROR, { detail: event });
    });
  }

  _setState(state) {
    this.state = state;
  }

  // MediaStatus's customData is how the receiver reports back to whichever
  // sender is connected — the mirror of customReceiverConfig on the way in.
  _dispatch(eventName, detail) {
    this.playerManager.broadcastCustomMessage(
      "urn:x-cast:com.yourapp.ott-receiver",
      { type: eventName, detail },
    );
  }
}

export default CafReceiverPlayer;